cat > main.go <<'EOF'
// Command mapdata demonstrates fluent access to arbitrary map data using objx.
package main

import (
	"fmt"

	"github.com/stretchr/objx"
)

func main() {
	m := objx.MustFromJSON(`{
		"name": "Ada",
		"address": {"city": "London"},
		"tags": ["math", "computing"]
	}`)

	fmt.Println(m.Get("name").Str())                  // Ada
	fmt.Println(m.Get("address.city").Str())          // London
	fmt.Println(m.Get("tags[1]").Str())               // computing
	fmt.Println(m.Get("missing").Str("default"))      // default

	m.Set("address.country", "UK")
	fmt.Println(m.Get("address.country").Str())       // UK

	merged := m.Merge(objx.Map{"born": 1815})
	fmt.Println(merged.Get("born").Int())             // 1815

	js, _ := merged.JSON()
	fmt.Println(js)
}
EOF
cat > main_test.go <<'EOF'
package main

import (
	"testing"

	"github.com/stretchr/objx"
)

func TestFluentAccess(t *testing.T) {
	m := objx.New(map[string]interface{}{
		"user": map[string]interface{}{
			"name":  "Ada",
			"roles": []interface{}{"admin", "dev"},
		},
	})

	if got := m.Get("user.name").Str(); got != "Ada" {
		t.Errorf("user.name = %q, want %q", got, "Ada")
	}
	if got := m.Get("user.roles[0]").Str(); got != "admin" {
		t.Errorf("user.roles[0] = %q, want %q", got, "admin")
	}
	if got := m.Get("user.age").Int(42); got != 42 {
		t.Errorf("user.age default = %d, want 42", got)
	}

	m.Set("user.email", "ada@example.com")
	if !m.Has("user.email") {
		t.Error("expected user.email to be set")
	}
}
EOF
